import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long k = nextLong();
        final long LIM = 1_000_000_000_000_000_000L;
        // All positive powers of k up to 10^18 (at most 60 of them); check before multiplying to avoid overflow.
        HashSet<Long> powers = new HashSet<>();
        for (long p = k; ; p *= k) {
            powers.add(p);
            if (p > LIM / k) break;
        }
        long c = 0;
        for (int i = 0; i < n; i++) if (powers.contains(nextLong())) c++;
        System.out.println(c);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() uint64 { sc.Scan(); v, _ := strconv.ParseUint(sc.Text(), 10, 64); return v }
	n, k := int(next()), next()
	const lim uint64 = 1_000_000_000_000_000_000
	// All positive powers of k up to 10^18 (at most 60 of them); check before multiplying to avoid overflow.
	powers := map[uint64]bool{}
	for p := k; ; p *= k {
		powers[p] = true
		if p > lim/k {
			break
		}
	}
	c := 0
	for i := 0; i < n; i++ {
		if powers[next()] {
			c++
		}
	}
	fmt.Println(c)
}
